const empresa = $input.item.json;
const prompt = "Eres consultor de marketing digital senior con 15 anos de experiencia en el mercado espanol. Analiza esta empresa y genera un diagnostico de marketing brutal y honesto. Empresa: " + empresa.nombre + ". Sector: " + empresa.sector + ". Ciudad: " + empresa.ciudad + ". Web: " + empresa.url_web + ". Problemas detectados: " + empresa.senales_dolor + ". Genera el diagnostico con estas secciones exactas respondiendo SOLO con JSON sin texto adicional ni markdown: problema_1 (string con el primer problema especifico con datos concretos), problema_2 (string con el segundo problema), problema_3 (string con el tercer problema), coste_mensual_estimado (string con lo que pierde en euros por estos problemas), accion_1 (string con primera accion concreta para los proximos 30 dias), accion_2 (string con segunda accion), accion_3 (string con tercera accion), oportunidad (string con la mayor oportunidad que tiene ahora mismo), resumen_ejecutivo (string de 2 frases resumiendo todo).";
const promptLimpio = prompt.replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim();
return { json: { ...empresa, prompt: promptLimpio } };

const response = $input.item.json;
const empresaData = $('Prepara Prompt Diagnostico').item.json;
let content = '';
if (response.content && Array.isArray(response.content)) {
  content = response.content[0].text || '';
} else if (response.text) {
  content = response.text;
} else {
  content = JSON.stringify(response);
}
let diagnostico;
try {
  content = content.replace(/```json/gi, '').replace(/```/g, '').trim();
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    diagnostico = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON');
  }
} catch(e) {
  diagnostico = {
    problema_1: 'Sin presencia digital efectiva',
    problema_2: 'Competencia captando sus clientes potenciales',
    problema_3: 'Sin sistema de captacion activo',
    coste_mensual_estimado: '2.000-5.000 euros/mes en oportunidades perdidas',
    accion_1: 'Activar Google My Business y responder reseñas',
    accion_2: 'Lanzar campana de Google Ads local',
    accion_3: 'Crear perfil de Instagram activo',
    oportunidad: 'Mercado local sin competencia digital fuerte',
    resumen_ejecutivo: 'La empresa tiene potencial sin explotar digitalmente.'
  };
}
return {
  json: {
    nombre: empresaData.nombre || '',
    sector: empresaData.sector || '',
    ciudad: empresaData.ciudad || '',
    url_web: empresaData.url_web || '',
    email_decisor: empresaData.email_decisor || '',
    nombre_decisor: empresaData.nombre_decisor || '',
    senales_dolor: empresaData.senales_dolor || '',
    diagnostico: diagnostico
  }
};

const datos = $input.item.json;
const d = datos.diagnostico;
const promptEmail = "Eres el director de una agencia de marketing digital en Espana llamada Impulsa Agency. Escribe un email frio personalizado para el decisor de esta empresa. Nombre decisor: " + datos.nombre_decisor + ". Empresa: " + datos.nombre + ". Sector: " + datos.sector + ". Ciudad: " + datos.ciudad + ". Problema principal detectado: " + d.problema_1 + ". Coste estimado del problema: " + d.coste_mensual_estimado + ". El email debe: tener maximo 5 lineas, mencionar algo especifico y real de su negocio, generar curiosidad sobre el diagnostico completo, terminar con un CTA para ver el diagnostico completo en el enlace privado, sonar como lo escribiria una persona real no una empresa. NO uses frases como Espero que este email te encuentre bien ni Me pongo en contacto. Responde SOLO con JSON sin markdown: asunto (string), cuerpo (string con el email completo con saltos de linea representados como barra n).";
const promptLimpio = promptEmail.replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim();
return { json: { ...datos, prompt_email: promptLimpio } };

const response = $input.item.json;
const datosEmpresa = $('Prepara Prompt Email').item.json;
let content = '';
if (response.content && Array.isArray(response.content)) {
  content = response.content[0].text || '';
} else {
  content = JSON.stringify(response);
}
let emailData;
try {
  content = content.replace(/```json/gi, '').replace(/```/g, '').trim();
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    emailData = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON');
  }
} catch(e) {
  emailData = {
    asunto: 'Algo que encontramos sobre ' + datosEmpresa.nombre,
    cuerpo: 'Hola ' + datosEmpresa.nombre_decisor + ', hemos analizado ' + datosEmpresa.nombre + ' y encontramos algo importante. Te hemos preparado un diagnostico completo.'
  };
}
return {
  json: {
    ...datosEmpresa,
    email_asunto: emailData.asunto || '',
    email_cuerpo: emailData.cuerpo || ''
  }
};
